def scrub(self, text: str) -> str:
    import ast

    for value in self.values:
        if value in text:
            text = text.replace(value, "[REDACTED]")
    if len(text) >= 2 and text[0] == text[-1] and text[0] in "'\"":
        try:
            return ast.literal_eval(text)
        except (SyntaxError, ValueError):
            pass
    return text
